import { PASSWORD, USERS, expect, expectStatus, test } from "../../fixtures";

test.describe("sign out", () => {
  test("signing out clears the session cookie", { tag: "@AUTH-06" }, async ({ apiAs, request }) => {
    // Arrange: sign in as the seeded member
    const member = await apiAs("member");

    // Act: sign out
    const response = await member.post("/api/auth/logout");

    // Assert: 204 and the session cookie is cleared
    expect(response.status()).toBe(204);
    const cookie = response
      .headersArray()
      .find((h) => h.name.toLowerCase() === "set-cookie" && h.value.toLowerCase().startsWith("session="));
    expect(cookie, "expected a Set-Cookie header clearing the session cookie").toBeDefined();
    expect(cookie!.value).toMatch(/^session=(;|$)/);
    expect(cookie!.value.toLowerCase()).toMatch(/max-age=0|expires=thu, 01 jan 1970/);
  });
});
